def test_captured_carrier_receipt_and_negative_controls():
    seed=(Path(__file__).resolve().parents[2]/"tests/fixtures/gen3/firered_party_town.sav").read_bytes()
    assert not carrier_problems(CAPTURE,seed)
    for old,new in (("counter=0->1","counter=0->0"),("result=127","result=0"),
                    ("epoch=7 owned=1","epoch=8 owned=1"),
                    ("cb=0811EBD1","cb=080565B5"),
                    ("UI_DONE op=20 seq=7","MISSING"),
                    ("CHOICES_COPY 02","CHOICES_COPY 03"),
                    ("PREPARE_DONE seq=4 phase=2 saves=1","PREPARE_DONE seq=4 phase=2 saves=0")):
        assert carrier_problems(CAPTURE.replace(old,new),seed)
